# Reference values generated by the Python package (scripts/make_reference_vectors.py)
# and shared by both test suites, so that R and Python give the same results.
ref_file <- if (requireNamespace("testthat", quietly = TRUE))
  testthat::test_path("reference_vectors.csv") else "reference_vectors.csv"
ref <- read.csv(ref_file, stringsAsFactors = FALSE)
vec <- function(s) as.numeric(strsplit(s, ";", fixed = TRUE)[[1]])
alt_r <- function(a) if (a == "two-sided") "two.sided" else a

test_that("R reproduces the shared reference vectors", {
  for (i in seq_len(nrow(ref))) {
    row <- ref[i, ]
    x <- vec(row$x); trim <- row$trim; alt <- alt_r(row$alternative)
    r <- suppressWarnings(switch(row$kind,
      one = ttest_trimmed(x, row$mu0, trim, alternative = alt),
      paired = ttest_rel_trimmed(x, vec(row$y), trim, alternative = alt),
      two = ttest_ind_trimmed(x, vec(row$y), trim, alternative = alt)))
    est <- if (row$kind == "two") unname(r$estimate[1] - r$estimate[2])
           else unname(r$estimate)
    expect_equal(est, row$est, tolerance = 1e-8)
    expect_equal(r$stderr, row$se, tolerance = 1e-8)
    expect_equal(unname(r$statistic), row$t, tolerance = 1e-8)
    expect_equal(unname(r$parameter), row$df, tolerance = 1e-8)
    expect_equal(r$p.value, row$p, tolerance = 1e-8)
    expect_equal(r$conf.int[1], row$ci_lo, tolerance = 1e-8)
    expect_equal(r$conf.int[2], row$ci_hi, tolerance = 1e-8)
    if (row$kind == "two")
      expect_equal(r$effect_size, row$effect, tolerance = 1e-8)
  }
})
